// =====================================================================
// موتور انتخاب الگو و محاسبه‌ی تمایلات رفتاری بر اساس نمره‌های D/I/S/C
// ورودی: درصد چهار بُعد (۰..۱۰۰) — خروجی: کلید الگو، کد الگو، تمایلات
// =====================================================================
function feria_disc_detect_pattern(array $pct): string {
    // کپی و مرتب‌سازی نزولی
    $s = $pct; arsort($s);
    $keys = array_keys($s); $vals = array_values($s);
    $mx = $vals[0]; $mn = $vals[3];
    // ۱) الگوی متعادل: هیچ بُعدی به‌وضوح از دیگران برجسته‌تر نیست
    //    (نسبت به مدل مرجع: وقتی پراکندگی نمرات کم باشد، گزارش «متعادل» می‌شود)
    if ($mx - $mn <= 12) return 'BA';
    if ($mx < 52)        return 'BA';   // نمره‌ی بالاترین بُعد هم از مرز «تمایل» پایین‌تر است
    // ۲) الگوی دو بُعدی: بُعد دوم نیز برجسته و فاصله‌اش با بُعد اول کوچک باشد
    if ($vals[1] >= 52 && ($mx - $vals[1]) <= 16) {
        $pair = [$keys[0], $keys[1]];
        // کلید استاندارد: ترتیب ثابت D<I<S<C بر اساس رشته‌ی 'DISC'
        usort($pair, function($a, $b) { return strpos('DISC', $a) <=> strpos('DISC', $b); });
        return implode('', $pair);
    }
    // ۳) الگوی تک‌بُعدی
    return $keys[0];
}

/** کد عددی الگو (۴ رقم) — سگمنتِ ۱ تا ۷ هر بُعد به ترتیب ثابت D،I،S ،C
 *  (منطبق با قالب «کد الگو» در گزارش‌های مرجع حرفه‌ای دیسک: هر بُعد یک سگمنت)
 *  نسخهٔ ۲٫۶: از تقسیم‌بر ده تغییر کرد به سگمنت‌های استاندارد ۱–۷ — مثل گزارش مرجع */
function feria_disc_pattern_code(array $pct): string {
    if (!function_exists('feria_disc_segment')) require_once __DIR__ . '/disc-deep-data.php';
    $out = '';
    foreach (['D','I','S','C'] as $d) {
        $out .= (string)feria_disc_segment(max(0, min(100, (int)($pct[$d] ?? 0))));
    }
    return $out;
}

/** محاسبه‌ی تمایلات رفتاری از روی میانگین وزنی نمره‌ی ابعاد (۰..۱۰۰) */
function feria_disc_tendencies(array $pct): array {
    global $FERIA_DISC_TENDENCIES;
    $out = [];
    foreach ($FERIA_DISC_TENDENCIES as $t) {
        $sumW = 0; $sum = 0;
        foreach ($t['w'] as $dim => $w) {
            $sumW += $w;
            $sum  += $w * max(0, min(100, (int)($pct[$dim] ?? 0)));
        }
        $p = $sumW > 0 ? (int)round($sum / $sumW) : 50;
        // سطح کیفی تمایل
        if ($p >= 80)      { $lv = 'خیلی بالا';  $cl = 'red';    $side = 'right'; }
        elseif ($p >= 62)  { $lv = 'بالا';        $cl = 'premium';$side = 'right'; }
        elseif ($p >= 45)  { $lv = 'متوسط';       $cl = 'purple'; $side = 'mid';   }
        elseif ($p >= 26)  { $lv = 'پایین';       $cl = 'blue';   $side = 'left';  }
        else               { $lv = 'خیلی پایین';  $cl = 'green';  $side = 'left';  }
        // برچسب سمت غالب: اگر تمایل به چپ بود، عنوان سمت چپ را نشان می‌دهیم
        $label = $side === 'left' ? $t['left'] : ($side === 'right' ? $t['right'] : 'متعادل');
        $out[] = [
            'title' => $t['title'], 'left' => $t['left'], 'right' => $t['right'],
            'pct' => $p, 'level' => $lv, 'chip' => $cl, 'side' => $side, 'label' => $label,
        ];
    }
    return $out;
}

/** سطح کیفی درصد هر بُعد */
function feria_disc_dim_level(int $pct): array {
    if ($pct >= 75) return ['بسیار برجسته', '#dc2626'];
    if ($pct >= 60) return ['برجسته', '#f59e0b'];
    if ($pct >= 45) return ['متعادل', '#7c3aed'];
    if ($pct >= 30) return ['آرام', '#3b82f6'];
    return ['بسیار آرام', '#10b981'];
}

// =====================================================================
// نسخه‌ی ۱.۰.۹ — محاسبات دقیق‌تر موتور دیسک:
//  الف) نمودارهای «طبیعی» و «تطبیق‌یافته» از پاسخ‌های «کمترین/بیشترین»
//  ب) نمره‌ی واقعی شاخص‌های هر بُعد (به‌جای نمایش صرف متن، درصد محاسبه شود)
//  ج) کلمات/عبارات تعدیل‌کننده‌ی رفتار (کلمات تعدیل لایه‌ی مرجع)
// =====================================================================

/**
 * سطح کیفی یک شاخص درصدی (برچسب + کلاس چیپ) — منطبق با قالب گزارش مرجع
 */
function feria_disc_trait_level(int $p): array {
    if ($p >= 80) return ['خیلی بالا', 'red'];
    if ($p >= 62) return ['بالا', 'premium'];
    if ($p >= 45) return ['متوسط', 'purple'];
    if ($p >= 26) return ['پایین', 'blue'];
    return ['خیلی پایین', 'green'];
}

/**
 * نمره‌ی واقعی هر «شاخص بُعد» از پاسخ‌های کاربر محاسبه می‌شود.
 * سازوکار: گزینه‌های هر سؤال به یکی از ۷ شاخصِ همان بُعد نگاشت می‌شود
 * (سؤال i ام → شاخص i٪۷)؛ با ۲۸ سؤال، هر شاخص ۴ سؤال اختصاصی دارد.
 * امتیاز خام شاخص = (تعداد بار انتخاب «بیشترین» − «کمترین») در گزینه‌های آن شاخص
 * و سپس به روی خط ۰..۱۰۰ برده می‌شود و با نمره‌ی کلی همان بُعد لنگر می‌ماند
 * تا هم از پاسخ‌های واقعی بیاید و هم با نتایج کلی تست روانشناسی سازگار بماند.
 *
 * @return array [ 'D' => [ ['name'=>..,'pct'=>..,'level'=>..,'chip'=>..], ... ], ... ]
 */
function feria_disc_trait_scores(array $questions, array $answers, array $pct, array $meta): array {
    global $FERIA_DISC_TRAITS;
    $sum = []; $cnt = [];
    $i = 0;
    foreach ($questions as $q) {
        $t = $i % 7; $i++;
        $a = $answers[$q['id']] ?? null;
        if (!$a || empty($a['most']) || empty($a['least'])) continue;
        foreach (['most' => +1, 'least' => -1] as $kind => $sgn) {
            $d = $a[$kind];
            if (!isset($FERIA_DISC_TRAITS[$d][$t])) continue;
            $key = $d . '_' . $t;
            $sum[$key] = ($sum[$key] ?? 0) + $sgn;
            $cnt[$key] = ($cnt[$key] ?? 0) + 1;
        }
    }
    $out = [];
    foreach (['D','I','S','C'] as $d) {
        $dimPct = max(0, min(100, (int)($pct[$d] ?? 50)));
        $list = [];
        foreach (array_keys($FERIA_DISC_TRAITS[$d]) as $t) {
            $key = $d . '_' . $t;
            $k = max(1, (int)($cnt[$key] ?? 4));
            // امتیاز خام در بازه‌ی [−k, +k] → نرمال به ۰..۱۰۰
            $raw = isset($sum[$key]) ? (int)round((($sum[$key] + $k) / (2 * $k)) * 100) : $dimPct;
            // لنگر روی نمره‌ی بُعد (۶۵٪ پاسخ‌های واقعی + ۳۵٪ سطح کلی بُعد)
            $p = (int)round(0.65 * $raw + 0.35 * $dimPct);
            $p = max(0, min(100, $p));
            [$lv, $lvChip] = feria_disc_trait_level($p);
            $list[] = [
                'name'  => $FERIA_DISC_TRAITS[$d][$t]['name'],
                'text'  => $FERIA_DISC_TRAITS[$d][$t]['text'],
                'pct'   => $p, 'level' => $lv, 'chip' => $lvChip,
            ];
        }
        $out[$d] = $list;
    }
    return $out;
}

/**
 * شاخص «جابه‌جایی رفتاری» (تفاوت نمودار طبیعی و تطبیق‌یافته)
 * $natural = درصد «بیشترین» انتخاب‌شده‌ها  و  $adapted = درصد «کمترین» انتخاب‌شده‌ها
 * خروجی: عدد ۰..۱۰۰ + عنوان + متن تفسیر
 */
function feria_disc_shift(array $natural, array $adapted): array {
    $d = 0;
    foreach (['D','I','S','C'] as $x)
        $d += abs((int)($natural[$x] ?? 0) - (int)($adapted[$x] ?? 0));
    $idx = (int)round($d / 2);          // ۰..۱۰۰ (میانگین قدرمطلق اختلاف‌ها ×۲)
    if ($idx < 10)  return ['idx' => $idx, 'title' => 'همسویی بسیار بالا', 'ok' => true,
        'text' => 'نمودار طبیعی و تطبیق‌یافته‌ی شما تقریباً برهم منطبق‌اند؛ یعنی رفتاری که به‌طور طبیعی دارید با رفتاری که فکر می‌کنید محیط از شما می‌طلبد یکی است. این یک مزیت بزرگ است: انرژی شما صرف «بازی‌کردنِ نقش» نمی‌شود و محیطی که در آن هستید با ذات‌تان سازگار است.'];
    if ($idx < 20)  return ['idx' => $idx, 'title' => 'همسویی نسبی', 'ok' => true,
        'text' => 'تفاوت اندکی میان رفتار طبیعی و رفتار تطبیق‌یافته‌ی شما دیده می‌شود که کاملاً طبیعی است؛ بخش کوچکی از انرژی‌تان صرف سازگارکردن خود با انتظارات محیط می‌شود. اگر این وضعیت ادامه پیدا کند مشکلی ندارد، اما مراقب باشید فاصله بزرگ‌تر نشود.'];
    if ($idx < 30)  return ['idx' => $idx, 'title' => 'فاصله‌ی محسوس', 'ok' => false,
        'text' => 'میان رفتار طبیعی و رفتاری که برای موفقیت در محیط از خود نشان می‌دهید فاصله‌ی محسوسی وجود دارد؛ یعنی بخشی از انرژی شما روزانه صرف «سازگارشدن» می‌شود. اگر این حالت طولانی شود، احتمال خستگی پنهان و افت عملکرد وجود دارد؛ بررسی کنید کدام انتظارات محیطی واقعاً لازم است و کدام را می‌توانید با گفت‌وگو تغییر دهید.'];
    return ['idx' => $idx, 'title' => 'فاصله‌ی زیاد — احتمال فشار محیطی', 'ok' => false,
        'text' => 'اختلاف زیادِ دو نمودار نشان می‌دهد در حال حاضر رفتار طبیعی‌تان را به‌شکل چشمگیری تغییر می‌دهید تا با محیط سازگار شوید. این «جابه‌جایی رفتاری» در کوتاه‌مدت قابل تحمل است اما در بلندمدت هزینه‌ی روانی بالایی دارد. توصیه می‌شود فصل سوم و چهارم گزارش را با دقت مطالعه کنید و اگر امکان دارد با مشاور درباره‌ی فشار محیطی فعلی گفت‌وگو کنید.'];
}

