$FERIA_NEO_FULL = [
'N' => '<b>روان‌رنجوری (Neuroticism) — تحلیل علمی عمیق</b><br><br>نمره‌ی شما در این بُعد بالاست. سیستم عصبی شما به محرک‌های تهدیدآمیز حساسیت بیشتری دارد و پاسخ هیجانی شما سریع‌تر، شدیدتر و طولانی‌تر از میانگین جمعیت است.<br><br><b>شش وجهِ این بُعد در شما:</b><br>• <b>اضطراب (Anxiety):</b> نگرانیِ مدام، پیش‌بینیِ بدترین حالت، احساس خطر بدون تهدید عینی<br>• <b>خشمِ پرخاشگرانه (Angry Hostility):</b> تحریک‌پذیری، کینه‌توزی، احساسِ موردِستم real بودن<br>• <b>افسردگی (Depression):</b> تمایل به غم، احساس پوچی، از دست‌دادنِ لذت<br>• <b>خودآگاهیِ اجتماعی (Self-Consciousness):</b> شرم، حساسیت به قضاوت، ناراحتی در جمع<br>• <b>تکانشگری (Impulsiveness):</b> عملِ ناگهانی زیر فشار، رفتار بدون فکرِ قبلی<br>• <b>آسیب‌پذیری (Vulnerability):</b> دشواری در مدیریت استرس، احساسِ غرق‌شدن<br><br><b>پشتوانه‌ی علمی:</b> مطالعات تصویربرداری مغزی (fMRI) نشان می‌دهد افراد دارای روان‌رنجوری بالا، فعالیت بیشتری در آمیگدال (مرکز ترس مغز) و ارتباط کمتری بین آمیگدال و قشر پیش‌پیشانی (مرکز کنترل) دارند (Eysenck, 1967؛ DeYoung et al., 2007).<br><br><b>راهکارهای دارای پشتوانه علمی:</b><br>۱. <b>ذهن‌آگاهی (MBSR — Kabat-Zinn):</b> کاهش ۳۸٪ علائم اضطراب در ۸ هفته (Hofmann et al., 2010)<br>۲. <b>درمان شناختی-رفتاری (CBT):</b> بازساختاریِ افکار خودکار منفی — مؤثرترین درمان برای اختلالات اضطرابی و افسردگی (Hofmann et al., 2012)<br>۳. <b>تنظیم هیجان (DBT — Linehan):</b> تکنیک‌های «آرام‌سازی پیش‌رونده‌ی عضلانی» و «تنفس شکمی»<br>۴. <b>ورزش هوازی:</b> کاهش علائم روان‌رنجوری از طریق افزایش سروتونین و BDNF (Cooney et al., 2013)<br><br><b>نکته‌ی کلیدی:</b> روان‌رنجوری، نه ضعف و نه بیماری است؛ یک ویژگی زیستی است که با آگاهی و تمرین قابل تنظیم است. هدف، نه حذف احساسات، بلکه ایجاد فاصله بین «احساس» و «واکنش» است.',
'E' => '<b>برون‌گرایی (Extraversion) — تحلیل علمی عمیق</b><br><br>نمره‌ی شما در این بُعد بالاست. مغز شما در پاسخ به پاداش‌های اجتماعی — تعامل، توجه، تأیید — دوپامینِ بیشتری ترشح می‌کند (Depue & Collins, 1999). این یعنی جمع‌بودن برای شما نه فقط لذت‌بخش، بلکه بیولوژیکی «شارژکننده» است.<br><br><b>شش وجه:</b><br>• <b>گرمی (Warmth):</b> صمیمی، دوست‌داشتنی، آغوش‌باز<br>• <b>اجتماعی‌بودن (Gregariousness):</b> لذت از جمع، نیاز به تعامل<br>• <b>قاطعیت (Assertiveness):</b> رهبری، سخن‌گویی، تصمیم‌گیری<br>• <b>فعالیت (Activity):</b> پرانرژی، پرسرعت، همیشه در حرکت<br>• <b>جست‌وجوی هیجان (Excitement-Seeking):</b> ریسک، تازگی، هیجان<br>• <b>احساساتِ مثبت (Positive Emotions):</b> خنده، شادی، خوش‌بینی<br><br><b>نکته‌ی بالینی:</b> برون‌گراییِ بالا، در انزوای طولانی (دورکاری، قرنطینه) می‌تواند به افت خلق، بی‌قراری و حتی علائم افسردگی منجر شود. تأمین نیاز اجتماعی برای شما نه لوکس، بلکه ضرورتِ سلامت روان است.<br><br><b>مسیر رشد:</b> تواناییِ تحملِ سکوت و تنهایی، گوش‌دادنِ عمیق (به‌جای همیشه حرف‌زدن) و یافتن منابعِ درونیِ انرژی (نه فقط بیرونی) نقاطِ رشد شما هستند.',
'O' => '<b>گشودگی به تجربه‌ها (Openness) — تحلیل علمی عمیق</b><br><br>نمره‌ی شما در این بُعد بالاست. ذهن شما کنجکاو، خلاق و علاقه‌مند به زیبایی، ایده‌های نو و تفکر انتزاعی است. McCrae و Costa (1997) همبستگیِ معناداری بین گشودگیِ بالا و خلاقیتِ هنری/علمی یافتند.<br><br><b>شش وجه:</b><br>• <b>تخیل (Fantasy):</b> ذهنِ پرهیجان، توانایی تصورِ دنیاهای متنوع<br>• <b>زیبایی‌شناسی (Aesthetics):</b> حساسیت به هنر، موسیقی، طبیعت<br>• <b>احساسات (Feelings):</b> عمقِ تجربه‌ی هیجانی، آگاهی از احساسات درونی<br>• <b>اقدامات (Actions):</b> تمایل به تنوع در زندگی روزمره<br>• <b>ایده‌ها (Ideas):</b> کنجکاویِ فکری، لذت از حل مسئله<br>• <b>ارزش‌ها (Values):</b> باز بودن به ارزش‌ها و سبک‌های زندگی متفاوت<br><br><b>پشتوانه‌ی علمی:</b> مطالعات fMRI نشان می‌دهد گشودگیِ بالا با افزایش ارتباط بین شبکه‌های پیش‌پیشانی و پیش‌credit همراه است — پایه‌ی تفکر خلاق و انعطاف‌پذیر شناختی.<br><br><b>مسیر رشد:</b> نوآوریِ شما قدرت است اما بدون نظم و اجرا، به daydreaming تبدیل می‌شود. مهارتِ «تبدیل ایده به پروژه»، نقاط قوت شما را به دستاورد تبدیل می‌کند.',
'A' => '<b>توافق‌پذیری (Agreeableness) — تحلیل علمی عمیق</b><br><br>نمره‌ی شما در این بُعد بالاست. شما دلسوز، همکار، صادق و قابل‌اعتماد هستید. Graziano & Eisenberg (1997) نشان دادند توافق‌پذیریِ بالا، پیش‌بینی‌کننده‌ی موفقیت در روابط بلندمدت و رضایت زناشویی است.<br><br><b>شش وجه:</b> اعتماد، صراحت، ازخودگذشتگی، انطباق، فروتنی، دلسوزی.<br><br><b>مسیر رشد:</b> دلسوزیِ شما، وقتی بدون مرز باشد، به قیمتِ حقوقِ شخصی‌تان تمام می‌شود. توانایی «نه» گفتنِ محترمانه، مهارتِ کلیدیِ رشد شماست.',
'C' => '<b>وظیفه‌شناسی (Conscientiousness) — تحلیل علمی عمیق</b><br><br>نمره‌ی شما در این بُعد بالاست. شما منظم، هدف‌محور و متعهد هستید. Roberts et al. (2007) نشان دادند وظیفه‌شناسی، قوی‌ترین پیش‌بینی‌کننده‌ی موفقیت تحصیلی و شغلی در میان پنج عامل است.<br><br><b>شش وجه:</b> شایستگی، نظم، تعهد، تلاش برای دستاورد، خودانضباط، احتیاط.<br><br><b>مسیر رشد:</b> بالاترین نقطه‌ی رشد شما، انعطاف‌پذیری و پذیرش «خوب به‌جای کامل» است.',
];

