$FERIA_YSQ_FULL = [
'ED' => 'شما در اعماق وجودتان احساس می‌کنید که نیازهای عاطفی‌تان — محبت گرم، درک واقعی، همراهی — هرگز به‌طور کامل برآورده نمی‌شود. این طرحواره اغلب از کودکی‌ای ریشه می‌گیرد که در آن، محبت مشروط، کم یا سرد بوده است.<br><br><b>ریشه‌ها</b><br>کودکی‌ای که در آن نیازهای عاطفی اساسی به‌طور پایدار تأمین نشد: والدین سرد، غایب یا درگیر مشکلات خودشان.<br><br><b>در زندگی امروز شما</b><br>انتخاب شریک‌هایی که از نظر عاطفی سرد یا غایب‌اند (تأیید مجدد طرحواره)؛ دوری از نزدیکی واقعی به‌خاطر ترس از ناامیدی؛ و احساس پوچی در میان جمع — انگار کسی واقعاً شما را نمی‌بیند.<br><br><b>مسیر درمان</b><br>شناسایی و نام‌گذاری نیازهای عاطفی؛ یادگرفتن خواستن آن‌ها در روابط امن؛ و مکث آگاهانه حین دریافت توجه — اجازه دادن محبت به دستتان برسد.<br><br><b>تمرین عملی این هفته</b><br>هر روز یک نیاز کوچک (یک گفت‌وگو، یک آغوش، یک گوش‌دادن) را از فردی مطمئن بخواهید و واکنشش را بدون قضاوت بنگرید. نیاز داشتن طبیعی است؛ مسئله، یادگرفتنِ خواستنِ آن است.',
'AB' => 'ترس بنیادین اینکه افراد مهم زندگی‌تان شما را ترک کنند یا رابطه ناپایدار باشد. این ترس گاهی به چسبیدن بیش‌ازحد یا دورکردن پیش‌دستانه منجر می‌شود.<br><br><b>ریشه‌ها</b><br>جدایی‌های ناگهانی دوران کودکی: فوت، طلاق، بیماری یا فراز و فرود عاطفی شدید والدین. سیستم هشدارِ وابستگی شما هنوز فعال است.<br><br><b>در زندگی امروز شما</b><br>تماس‌های پی‌درپی، حسادت کنترلی، یا برعکس — دوری پیش‌دستانه برای جلوگیری از دردِ جدایی. شواهد امن و پایدار در حافظه‌تان کم‌رنگ نگه داشته می‌شود.<br><br><b>مسیر درمان</b><br>ساخت «بانک شواهد» از روابط پایدار؛ تکنیک زمین‌گذاری ۵-۴-۳-۲-۱ برای لحظات سیل احساسی؛ و تحملِ تدریجیِ فواصل کوتاه با بازگشتِ قابل‌پیش‌بینی.<br><br><b>تمرین عملی</b><br>دفترِ اضطرابِ جدایی بنویسید: محرک، فکر، احساس بدن و رفتار را ثبت کنید. بعد بازبینی کنید: چند مورد از پیش‌بینی‌های بدِ شما واقعاً اتفاق افتاد؟ داده، از ذهن دقیق‌تر است.',
'MA' => 'انتظار دارید دیگران از شما سوءاستفاده می‌کنند، فریب می‌دهند یا نیت پنهان دارند. مراقبت دائمی از خود، آسانِ شماست اما به قیمتِ فاصله از صمیمیت تمام می‌شود.<br><br><b>ریشه‌ها</b><br>تجربه‌هایی از خیانت، سوءاستفاده یا ناامیدی جدی در روابط اولیه. مغز شما آموخته: «هر کس، بالقوه خطرناک است.»<br><br><b>در زندگی امروز شما</b><br>مراقبت بیش‌ازحد از اطلاعات شخصی؛ تفسیر منفیِ رفتارهای مبهم؛ محکم‌کاری در قراردادها؛ و دوری از صمیمیت واقعی.<br><br><b>مسیر درمان</b><br>تفکیک «گذشته‌ی واقعی» از «الگوی تعمیم‌یافته»؛ تمرین اعتمادِ طبقه‌بندی‌شده (افشای کوچک و تست‌ریسک امن)؛ و بررسی شواهد طرفین در لحظه‌ی بدگمانی.<br><br><b>تمرین عملی</b><br>این هفته، یک اطلاعات کوچکِ شخصی (غیر حساس) را به فردی مطمئن بگویید و ببینید چه اتفاقی می‌افتد. اغلب، واقعیت خشنودکننده‌تر از پیش‌بینیِ محتاطانه‌ی ذهن شماست.',
'SI' => 'احساس متفاوت‌بودن و بیرون‌ماندن از گروه؛ انگار هیچ دایره‌ی اجتماعی واقعاً جای شما نیست.<br><br><b>ریشه‌ها</b><br>خانواده‌ای متفاوت از همتایان، مهاجرت، تفاوت‌های فرهنگی یا تجربه‌ی طرد در گروه‌های کودکی.<br><br><b>در زندگی امروز شما</b><br>اجتناب از جمع‌ها، تقلید افراطی از سبک دیگران برای جبران، یا حضور فیزیکی با پنهان‌کاریِ خودِ واقعی. شما نسبت به پیام‌های غیرکلامی بسیار حساس‌تر از بقیه هستید — که خود می‌تواند هدیه باشد.<br><br><b>مسیر درمان</b><br>چالش باورهای کلیشه‌ای («همه مرا رد می‌کنند»)؛ ورود تدریجی به گروه‌های کوچک و ایمن؛ و ساختن «جامعه‌ی منتخب» بر اساس علایق واقعی.<br><br><b>تمرین عملی</b><br>به یک گروهِ کوچکِ مرتبط با علاقه‌ی واقعی‌تان (کتاب، ورزش، هنر) بپیوندید. هدف، دوست‌یابی فوری نیست؛ فقط حضور و آزمودنِ تجربه‌ی «جای من اینجاست».',
'DS' => 'باور درونی اینکه در جنبه‌ی مهمی «معیوب و دوست‌نداشتنی» هستید و اگر دیگران شما را واقعاً بشناسند، پس می‌زنند.<br><br><b>ریشه‌ها</b><br>پیام‌های تکرارشونده‌ی دوران فرزندی: مقایسه‌ی تحقیرآمیز، سرزنش به‌جای نقد رفتار، یا محیطی که اشتباه، لغزش مهلک تلقی می‌شد.<br><br><b>در زندگی امروز شما</b><br>پنهان‌کاری (خود را بدون حریم خصوصی نشان دادن)، جبران (تلاش برای کمال پوشاننده)، یا اجتناب از نزدیکی حقیقی. هرچه بیشتر پنهان می‌کنید، کم‌رنگ‌تر می‌شوید.<br><br><b>مسیر درمان</b><br>مواجهه‌ی تدریجی با ترس طرد در قالب افشای کنترل‌شده؛ بازنویسی گفت‌وگوی درونی از «من خرابم» به «من انسانم».<br><br><b>تمرین عملی</b><br>این هفته یک موضوع کوچک (غیرامنیتی) را به آدمی امن بگویید و واکنشش را واقع‌بینانه بنگرید. آسیب‌پذیری، اعلامِ ورشکستگی نیست؛ ویژگیِ انسانی است.',
'FA' => 'باور قانع‌کننده‌ای که شما «طبیعتاً» در سطحِ کافی قرار ندارید: تحصیل، شغل یا دستاوردها. این باور، فرصت‌ها را پیش از آغاز کوچک می‌کند.<br><br><b>ریشه‌ها</b><br>مقایسه‌های مداوم والدین یا مربیان؛ پیام‌های «سرقت‌راهی» یا تجربه‌هایی که تلاش فراتر از استعداد، تأیید نشد.<br><br><b>در زندگی امروز شما</b><br>کوچک‌شمردن موفقیت‌ها («اتفاقی شد»)؛ اجتناب از فرصت‌ها پیش از تجربه؛ شکستن پروژه نیمی از راه؛ و احساس «کلاهبرداری» — انگار زود یا دیر، همه می‌فهمند شما «به‌اندازه‌ی کافی» خوب نیستید.<br><br><b>مسیر درمان</b><br>تکنیک «ثبت دستاوردها و شواهد» هفتگی؛ آزمایش رفتاری (پروژه‌ی کوچک با معیار روشن)؛ و بازتعریف موفقیت بر اساس معیارهای شخصی، نه مقایسه.<br><br><b>تمرین عملی</b><br>هر جمعه، ۳ دستاوردِ هفته را بنویسید — حتی کوچک. بعد بازخوانی کنید: آیا این‌ها کارِ «اتفاقی» بودند یا تلاشِ شما؟ آنچه طرحواره می‌گوید، داده نیست؛ خاطره‌ای قدیمی است.',
'DI' => 'احساس اینکه برای اداره‌ی زندگی روزمره، به دیگران بیش از حد نیاز دارید. اعتمادبه‌نفس کاری شما زیر سایه‌ی این باور فرسوده می‌شود.<br><br><b>ریشه‌ها</b><br>محیطی که بیش‌ازحد محافظت‌گر بود (اجازه‌ی خطا نمی‌داد) یا بی‌توجه بود (فرزند با موانع تنها می‌ماند). نتیجه‌ی هر دو: «من به‌تنهایی از عهده برنمی‌آیم».<br><br><b>در زندگی امروز شما</b><br>در آستانه‌ی تصمیم‌های کاربردی، ناخودآگاه به دنبال «فرد نجات‌دهنده» می‌گردید. حس انرژی‌تان با قطعیتِ دیگران شارژ می‌شود و تصمیم‌گیریِ مستقل، ترسناک است.<br><br><b>مسیر درمان</b><br>آموزش «مهارت‌های خوداتکایی خُرد»: هر روز یک تصمیم کوچک بدون مشورت. ثبت موقعیت‌هایی که بدون راهنمایی هم موفق بودید.<br><br><b>تمرین عملی</b><br>هر روز این هفته، یک کارِ اجراییِ کوچک (خرید، تماس، تنظیم) را کاملاً مستقل انجام دهید و بعد بنویسید: «من این را به‌تنهایی کردم». توانمندی شما ساخته‌شدنی‌تر از آن است که فکر می‌کنید.',
'VH' => 'زندگی روزمره‌ی شما در محاصره‌ی «اگرهای» ترسناک است. ذهن مدام در حالت هوشیاری است و انرژی زیادی صرف پیش‌نویس بدترین سناریوها می‌کنید.<br><br><b>ریشه‌ها</b><br>تجربه‌های تروماتیک (حادثه، بحران سلامت در خانواده) یا فضای روانیِ پر از اضطراب که «محافظت دائمی = امنیت» آموخته.<br><br><b>در زندگی امروز شما</b><br>اجتناب از سفر، تجربه‌های جدید یا تصمیم‌های منطقی به‌خاطر ترس از «چه‌شود اگر». چک‌کردن‌های بیمارگونه. هراسِ پیش‌بینانه، انرژیِ زندگی را می‌گیرد.<br><br><b>مسیر درمان</b><br>کاهش تدریجی اجتناب‌ها (سلسله‌مراتب مواجهه)؛ تکنیک تنفس ۴-۷-۸؛ و تفکیک «احتیاط سالم» از «هراس‌زدگی». قانون عملی: اگر اقدام، با بهترین اطلاعات در دسترس، قابل‌دفاع است — احتیاط است، نه هراس.<br><br><b>تمرین عملی</b><br>هر بار که ذهن سناریوی بد ساخت، بپرسید: «چقدر احتمال دارد؟» درصد بنویسید. بعد بازبینی کنید: چند مورد واقعاً اتفاق افتاد؟',
'EM' => 'مرزهای شما با خانواده محو است؛ زندگی‌تان به‌شدت با آن‌ها بافته شده و رشد فردی مستقل دشوار می‌شود. استقلال، احساس خیانت ایجاد می‌کند.<br><br><b>ریشه‌ها</b><br>خانواده‌ای که هویت فردی فرزند را به‌خاطر نیازهای عاطفی خود قربانی کرد؛ والدینی که فرزند، حاملِ مأموریت یا تسکینِ آن‌ها بود.<br><br><b>در زندگی امروز شما</b><br>وقتی می‌خواهید رشته، شغل، همسر یا محل زندگی‌تان را انتخاب کنید، صدای داخلی می‌گوید «خیانت می‌کنی». مرزسازی، گناه‌زا است.<br><br><b>مسیر درمان</b><br>تمرین «تفکیک هویت»: مشخص‌کردن ارزش‌ها و خواسته‌های شخصی مستقل از خانواده؛ ایجاد مرزهای قابل‌دفاع (زمان تماس، دخالت در تصمیم) و عذرخواهی‌نکردن بابت آن‌ها.<br><br><b>تمرین عملی</b><br>یک لیست بنویسید: «۳ چیزی که من می‌خواهم و خانواده‌ام لزوماً موافق نیستند». این تمرین، آغازِ گفت‌وگوی درونیِ «من، جدا از آن‌ها، کی هستم؟» است.',
'SU' => 'نیازها، احساسات و انتخاب‌های خود را به‌خاطر دیگران فدا می‌کنید تا درگیری پیش نیاید. در بلندمدت، خشم فروخورده و فرسودگی ایجاد می‌شود.<br><br><b>ریشه‌ها</b><br>خانه‌ای که بیان نیاز مجازات می‌شد یا فرزندی که با سکوت و انفعال، امنیت ایجاد کرد.<br><br><b>در زندگی امروز شما</b><br>انباشته‌شدن رنجش خفته که به انفجارهای بی‌محل یا خستگی مزمن تبدیل می‌شود. حتی در تصمیم‌های کوچک، ترجیحِ دیگران بر خواستِ شما مقدم است.<br><br><b>مسیر درمان</b><br>تکنیک ابراز وجود: جمله‌ی «من…» + بیان نیاز بدون عذرخواهی؛ تمرین روزانه‌ی «یک مخالفت کوچک»؛ و بیان خشم به‌صورت کنترل‌شده.<br><br><b>تمرین عملی</b><br>هر روز این هفته، در یک موقعیت کوچک، به‌جای «فرقی نداره»، بگویید «من این را ترجیح می‌دم». نظر شما ارزشمند است و گفتنش هیچ‌کس را دور نمی‌کند — سکوت است که فرسوده می‌کند.',
'SS' => 'رسیدگی به دیگران برای شما اجباری است و به خودتان رسیدن «خودخواهی» تلقی می‌شود.<br><br><b>ریشه‌ها</b><br>خانواده‌ای که ارزش فرزند را با «به‌کارآمدنی برای دیگران» می‌سنجید یا الگویی که خود فداکار بود.<br><br><b>در زندگی امروز شما</b><br>وقتی ایثار شما تعادل زمان و انرژی را زیر سؤال می‌برد، یا فرسودگی یا نارضایتی پنهان پدیدار می‌شود. مراقبت از دیگران، به قیمت محوشدنِ خودتان تمام می‌شود.<br><br><b>مسیر درمان</b><br>تمرین «بودجه‌ی انرژی»: زمان مقررِ رسیدگی به خود، مثل قرار ملاقاتی که لغو نمی‌شود. درک اینکه «خودمراقبتی، قطعی‌ترین سرمایه‌گذاری برای مراقبت از دیگران است».<br><br><b>تمرین عملی</b><br>این هفته، ۳۰ دقیقه برای خودتان «رزرو» کنید — برای کاری که فقط به شما لذت می‌دهد. احساس گناه طبیعی است؛ مهم این است که آن را تجربه کنید و اجازه دهید.',
'AS' => 'ارزش شما به تأیید و محبوبیت در چشم دیگران گره خورده است؛ نیاز مداوم به بازخورد مثبت، آزادی انتخاب‌تان را می‌گیرد.<br><br><b>ریشه‌ها</b><br>خانه و مدرسه‌ای که «چه می‌گویند» قدیس‌وار محترم بود و ارزش، با تأیید خارجی سنجیده می‌شد.<br><br><b>در زندگی امروز شما</b><br>تنظیم رفتار بر اساس بازخورد لحظه‌ای؛ حساسیت طاقت‌فرسا به علائم طرد؛ و روزهایی که خلق، به واکنشِ دیگران وابسته است.<br><br><b>مسیر درمان</b><br>ساخت ستون «ارزش‌های درونی» — ۳ ارزش اصلی که وابسته به نظر کسی نیستند؛ تمرین تصمیم‌های کوچک مستقل از ترسِ قضاوت.<br><br><b>تمرین عملی</b><br>این هفته، یک تصمیمِ کوچک (لباس، غذا، فعالیت) را فقط بر اساس خواستِ خودتان بگیرید — بدون پرسیدن از کسی. بعد بنویسید: «چه حسی داشت؟» تصویری که به دیگران نشان می‌دهید، زاییده‌ی خود واقعی‌تان باشد.',
'US' => 'احساسات را مهار و پنهان می‌کنید تا سرد و منطقی به نظر برسید. هزینه‌ی این مهار، فاصله از صمیمیت و خستگی روانی است.<br><br><b>ریشه‌ها</b><br>خانواده‌ای که ابراز احساس را ضعف می‌دانست یا مجازات می‌کرد.<br><br><b>در زندگی امروز شما</b><br>دیگران شما را سرد و دور می‌دانند در حالی که درون‌تان پر از حرف است. مهار احساس، آن را از بین نمی‌برد؛ انباشته می‌کند و مخارجش خواب گسسته، تنش بدنی و طوفان‌های ناگهانی است.<br><br><b>مسیر درمان</b><br>تمرین نمایش احساس در بستر امن (هفته‌ای دو بار ۱۰ دقیقه «گفتن حال واقعی» با یک فرد مطمئن)؛ نام‌گذاری روزانه‌ی احساسات؛ و کار بدنی برای آزادسازی انرژی مهارشده.<br><br><b>تمرین عملی</b><br>هر شب قبل از خواب، یک احساسِ امروز را نام‌گذاری کنید: «امروز احساس … کردم». فقط نام‌گذاری، بدون تحلیل. ابراز احساس قدرت است — قدرتِ مهرورزی.',
'UN' => 'استانداردهای شما فراتر از طبیعی است و هیچ نتیجه‌ای «کافی» نیست. کمال‌گرایی شما را به جلو می‌برد اما آسودگی را می‌گیرد.<br><br><b>ریشه‌ها</b><br>خانواده‌ای که عشق را با عملکرد مشروط می‌کرد یا فضای رقابتیِ سنگین که «کافی» هرگز کافی نبود.<br><br><b>در زندگی امروز شما</b><br>ساعت‌های اضافه‌کاری بی‌بازده؛ ناتوانی از جشن‌گرفتن موفقیت‌ها؛ و فشار به دیگران با همان استاندارد — که روابط را فرسوده می‌کند.<br><br><b>مسیر درمان</b><br>آموزش قاعده‌ی «به‌اندازه‌ی کافی خوب» در ۷۰٪ موارد؛ تمرین «اتمام ناقص» (تحویل کارِ خوب اما نه عالی) و تحمل ناراحتی‌اش.<br><br><b>تمرین عملی</b><br>این هفته، یک کار را در سطح «خوب» (نه عالی) تحویل دهید و ببینید چه اتفاقی می‌افتد. اغلب، هیچ فاجعه‌ای رخ نمی‌دهد. «خوبِ انجام‌شده»، بهتر از «کاملِ هرگز» است.',
'ET' => 'مرز «حق من» و «حق دیگران» نامتعادل است؛ گاهی انتظارات‌تان را مقدم بر قواعد و نیاز بقیه می‌دانید.<br><br><b>ریشه‌ها</b><br>خانواده‌ای که مسئولیت‌پذیری محدودی آموخت یا محیطی که استحقار پاداش می‌داد.<br><br><b>در زندگی امروز شما</b><br>عصبانیت از «انتظار ناکامی»؛ کاهش تحمل برای محدودیت‌های اجتماعی؛ و روابطی که به رقابت تبدیل می‌شوند چون تراز باید به سود شما بچرخد.<br><br><b>مسیر درمان</b><br>تمرین «من/تو معادله»: پیش از خواست، یک سؤال از نیازِ طرف بپرسید؛ بررسی هزینه‌ی میان‌مدتِ هر برخوردِ خودخواهانه؛ و آموزش تحمل سرخوردگی.<br><br><b>تمرین عملی</b><br>این هفته، پیش از هر درخواست، مکث کنید و بپرسید: «این خواست، حقِ طرف مقابل را زیر سؤال می‌برد؟» توازن، نه فروتنی، بلکه احترامِ متقابل است.',
'IS' => 'فاصله گرفتن از لذتِ لحظه‌ای به نفع هدفِ دور، برای شما سخت است؛ برنامه‌ها نیمه‌تمام می‌مانند و حس ناکامی تقویت می‌شود.<br><br><b>ریشه‌ها</b><br>خانواده‌ای که مرز و پایداری نداشت یا الگوهای راحت‌طلبانه‌ای که در نوجوانی تثبیت شد.<br><br><b>در زندگی امروز شما</b><br>شروع پرشور و اتمام ناتمام؛ وسوسه‌ها برنده می‌شوند و خودتان را سرزنش می‌کنید. این طرحواره با «تنبلی» تفاوت دارد؛ مسئله، مدیریتِ انگیزه‌ی تأخیرشده است.<br><br><b>مسیر درمان</b><br>آموزش مهارت‌های اجرایی (پومودورو، برنامه‌ی ۵ دقیقه‌ای شروع)؛ طراحی محیطی (حذف وسوسه‌های نزدیک)؛ و پاداش‌های کوتاه‌مدتِ سالم پس از هر پله.<br><br><b>تمرین عملی</b><br>«قصدِ اجرایی» بنویسید: «ساعت ۹ فردا، ۲۰ دقیقه روی X کار می‌کنم». دقیق، مشخص، قابل‌اجراء. انضباطی که از شفقت به خود سرچشمه بگیرد، پایدارتر از انضباطِ خشن است.',
'PU' => 'قاضیِ سختگیرِ درونی فعال است؛ خطای خودتان و دیگران به‌سختی بخشیده می‌شود و نرمش عاطفی آسان نیست.<br><br><b>ریشه‌ها</b><br>خانواده‌ای که بخشش را ضعف می‌دانست یا خودتان به‌شدت مجازات می‌شدید و این شدت را به ارث برده‌اید.<br><br><b>در زندگی امروز شما</b><br>ناتوانی از فراموش‌کردن؛ استفاده‌ی مکرر از «باید»؛ و سرزنشِ خودتان که خواب و خلق را زیر سؤال می‌برد.<br><br><b>مسیر درمان</b><br>تفکیک «رفتار» از «شخص» (خطا کردی، خراب نشدی)؛ تکنیک «نامه‌ی بخشش»؛ و جایگزینی تنبیه با بازسازی (repair).<br><br><b>تمرین عملی</b><br>این هفته، وقتی اشتباهی کردید، به‌جای «من آدمِ بدی هستم»، بگویید «من اشتباهی کردم». فرق این دو جمله، فرقِ بین مجازات و رشد است. بخشش، غریبه نیست؛ فقط لازم بود کسی اول به شما نشانش می‌داد.',
'NP' => 'ذهن شما به‌صورت خودکار بر خطرات و جنبه‌ی تاریک تمرکز می‌کند؛ این محافظتِ دائمی، انرژی لذت را کم می‌کند.<br><br><b>ریشه‌ها</b><br>محیط خانواده‌ای شکننده و پرنگرانی یا تجربه‌های مکرر سرخوردگی که «امید» را بی‌اعتبار کرده‌اند.<br><br><b>در زندگی امروز شما</b><br>حتی در خبرهای خوب، اول به جنبه‌ی منفی فکر می‌کنید؛ لذت‌ها با پس‌زمینه‌ی «به‌زودی تمام می‌شود» تجربه می‌شوند. توجهِ انتخابیِ مغز، فقط بخشی از اطلاعات را ثبت می‌کند.<br><br><b>مسیر درمان</b><br>تمرین «سه چیز درستِ امروز» (برای تصحیح لنز، نه انکار بد)؛ ثبت پیش‌بینی‌ها و بازبینی درصد تحقق؛ و ذهن‌آگاهی برای جداشدن از جریان افکار.<br><br><b>تمرین عملی</b><br>هر شب، سه چیزِ خوبِ روز را بنویسید — حتی کوچک. بعد هفت‌هفته بازخوانی کنید: آیا زندگی‌تان به‌اندازه‌ای تاریک بود که ذهن می‌گفت؟ عدالت در داده است، نه در پیش‌فرض.',
