// توصیه‌های کلی رشد موازی (در تحلیل ویژه پایانی می‌آید)
$FERIA_YSQ_GENERAL_ADVICE = 'این تحلیل بر اساس پاسخ‌های شما به پرسش‌نامه‌ی طرحواره‌های یانگ تهیه شده و تصویری تخصصی از الگوهای عمیق فکری-احساسی شما ارائه می‌دهد؛ اما جایگزین مصاحبه‌ی بالینی نیست. شدت هر طرحواره با زمان، رویدادها و آگاهی تغییر می‌کند. توصیه می‌شود: (۱) در هر طرحواره‌ی «برجسته»، تمرین‌های عملی آورده‌شده را حداقل ۴ هفته پیوسته دنبال کنید و تغییرات را بنویسید؛ (۲) اگر شدت طرحواره (≥۴/۵) یا فرورفتگی‌های دائمی دارید، با یک طرحواره‌درمانگر یاروان‌درمانگر تحصیل‌کرده مشورت کنید؛ (۳) این گزارش را هر ۶ ماه با تست روانشناسی مجدد مقایسه کنید تا مسیر رشد‌تان سند پیدا کند.';

// ---------------------------------------------------------------------
// توابع کمکی نمایش نام فارسی طرحواره و حیطه (بخش مدیریت سؤالات/خروجی‌ها)
// ---------------------------------------------------------------------
// نام فارسی طرحواره از روی کد (مثال: ED ← محرومیت عاطفی)
function ysq_schema_name(string $code): string {
    global $FERIA_YSQ_SCHEMAS;
    return $FERIA_YSQ_SCHEMAS[$code] ?? $code;
}
// حیطه‌ای که طرحواره به آن تعلق دارد (مثال: ED ← قطع و طرد شدگی)
function ysq_domain_name(string $code): string {
    global $FERIA_YSQ_DOMAINS;
    foreach ($FERIA_YSQ_DOMAINS as $dom => $codes)
        if (in_array($code, $codes, true)) return $dom;
    return '—';
}

